{"version":3,"sources":["powpow/general-purpose.css","powpow/general-purpose.scss"],"names":[],"mappings":"AAAA,gBAAgB;ACAhB;EAEI,6BAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,kBAAA;EACA,gBAAA;EACA,aAAA;EACA,mBAAA;EACA,uBAAA;EACA,gBAAA,EAAA,sCAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,kBAAA,EAAA,2DAAA;EACA,QAAA;EACA,SAAA;EACA,2CAAA,EAAA,qDAAA;EACA,uBAAA;EAAA,kBAAA,EAAA,kDAAA;EACA,wBAAA;EAAA,mBAAA,EAAA,mDAAA;EACA,cAAA,EAAA,wCAAA;EACA,gBAAA,EAAA,oCAAA;EACA,UAAA,EAAA,iDAAA;EACA,gBAAA,EAAA,6DAAA;EACA,mBAAA,EAAA,oDAAA;EACA,gDAAA,EAAA,sBAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,eAAA,EAAA,+CAAA;EACA,gBAAA,EAAA,6CAAA;EACA,sBAAA;KAAA,mBAAA,EAAA,8CAAA;EACA,YAAA;EACA,cAAA;EACA,4DAAA;EACA,sEAAA;ADCJ;;ACEA,6CAAA;AACA;EACI;IACI,2CAAA;IACA,gBAAA;EDCN;AACF;ACEA,mDAAA;AACA;EACI;IACI,yCAAA;IACA,gBAAA;EDAN;AACF;ACGA,yCAAA;AACA;EACI;IACI,2CAAA;IACA,iBAAA;EDDN;AACF;ACIA;EACI;IACI,2CAAA;IACA,iBAAA;EDFN;AACF;ACKA;EACI;IACI,yCAAA;IACA,iBAAA;EDHN;AACF;ACOA,kBAAA;AACA;EAII;IAEI,0BAAA;EDTN;ECYE;IAEI,YAAA;IACA,gBAAA;EDXN;ECcE;IAEI,8BAAA;EDbN;AACF;ACeA;;;;CAAA;AAKA;EAEI;IACI,gBAAA;IACA,eAAA;IACA,kBAAA;IAEA,WAAA;IACA,YAAA;IACA,sDAAA,EAAA,sBAAA;EDfN;ECkBE;IAEI,YAAA;IACA,gBAAA;EDjBN;ECoBE;IAEI,8BAAA;EDnBN;ECqBE;;;;GAAA;EAKA;IACI,eAAA;IACA,sCAAA;EDnBN;ECsBE;IACI,iBAAA;EDpBN;ECuBE;IACI,aAAA;EDrBN;ECwBE;IACI,cAAA;EDtBN;AACF;ACwBA;EAEI;IAEI,aAAA;EDxBN;EC2BE;IACI,iBAAA;EDzBN;AACF;ACgCA;;iDAAA;AAGA;EACI,kBAAA;EACA,UAAA;EACA,WAAA;AD9BJ;;ACiCA,yDAAA;AACA;EACI,cAAA;EACA,WAAA;AD9BJ;;ACiCA,oCAAA;AACA;;EAEI,YAAA;EACA,0CAAA;AD9BJ;;ACqCA;EACI,uBAAA;EACA,YAAA;EACA,UAAA;EACA,eAAA;EACA,cAAA,EAAA,4CAAA;EACA,aAAA,EAAA,oBAAA;EACA,oBAAA;EACA,mBAAA;EACA,QAAA;EACA,kDAAA;ADlCJ;;ACqCA;EACI,cAAA;ADlCJ;;ACqCA;EACI,eAAA;EACA,YAAA;EACA,SAAA;EACA,6CAAA;EACA,mBAAA;EACA,WAAA;EACA,kBAAA;EACA,mBAAA;EACA,kBAAA;EACA,gBAAA;EACA,qBAAA;EACA,2CAAA;EACA,UAAA;EACA,kDAAA;EACA,aAAA;EACA,oBAAA;EACA,mBAAA;ADlCJ;;ACqCA;EACI,UAAA;EACA,yCAAA;ADlCJ;;ACwCA,oDAAA;AACA,0CAAA;AACA;EACI;IACI,aAAA;EDrCN;ECuCE;IACI,eAAA;EDrCN;AACF;ACwCA;EACI;IACI,eAAA;EDtCN;ECwCE;IACI,aAAA;EDtCN;AACF;ACyCA;EAEI;IAEI,0BAAA;EDzCN;AACF;AC4CA;EACI;IACI,4BAAA;ED1CN;EC6CE;IACI,mBAAA;ED3CN;AACF;AC8CA,+DAAA;AACA;;;;EAII,4BAAA;EACA,8BAAA;AD5CJ;;AC+CA;EACI,yCAAA;EACA,8BAAA;AD5CJ;;AC+CA;EACI,4BAAA;AD5CJ;;AC+CA,2CAAA;AACA;EACI,wBAAA;AD5CJ;;AC+CA,wDAAA;AACA;EACI,wBAAA;EACA,8BAAA;EACA,4BAAA;AD5CJ;;AC+CA;EACI,wBAAA;AD5CJ;;AC+CA;EACI,8BAAA;EACA,yBAAA;EACA,gCAAA;AD5CJ;;AC+CA;EACI,sBAAA;EACA,uBAAA;EACA,0BAAA;AD5CJ;;AC+CA;EACI,8BAAA;EACA,iCAAA;EACA,4BAAA;AD5CJ;;AC+CA;EACI,8BAAA;EACA,yBAAA;AD5CJ;;AC+CA;EACI,yBAAA;AD5CJ","file":"general-purpose.css","sourcesContent":["@charset \"UTF-8\";\n.portfolio-options {\n  margin-bottom: 1em !important;\n}\n\n/* ============================================\n   BANNER: contenitore principale\n   ============================================ */\n.banner {\n  position: relative;\n  min-height: 82vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden; /* 👈 nasconde l'overflow del banner */\n}\n\n/* ============================================\n   VIDEO BACKGROUND: sfondo centrato (dietro al testo)\n   ============================================ */\n.video-background {\n  position: absolute; /* 👈 sta dietro al testo, non esce dal flusso del banner */\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%) scale(1.4); /* 👈 ingrandito del 40%, container e video insieme */\n  width: fit-content; /* 👈 stesso width del video, nessun bordo vuoto */\n  height: fit-content; /* 👈 stesso height del video, nessun bordo vuoto */\n  max-width: 95%; /* 👈 non esce dallo schermo su mobile */\n  max-height: 85vh; /* 👈 dimensione specifica altezza */\n  z-index: 0; /* 👈 dietro al testo (container ha z-index: 1) */\n  overflow: hidden; /* 👈 taglia il video agli angoli arrotondati del container */\n  border-radius: 30px; /* 👈 bordi arrotondati più visibili sul CONTAINER */\n  box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n}\n\n/* ============================================\n   VIDEO: stessa grandezza del container, aspect ratio preservato\n   ============================================ */\n.video-background video {\n  max-width: 100%; /* 👈 non esce mai dal container in larghezza */\n  max-height: 100%; /* 👈 non esce mai dal container in altezza */\n  object-fit: contain; /* 👈 mantiene l'aspect ratio, nessun taglio */\n  opacity: 60%;\n  display: block;\n  /* nessun position: absolute: sta nel flusso del container */\n  /* nessun border-radius: sta solo sul container con overflow: hidden */\n}\n\n/* Schermi sotto i 1400px: video più grande */\n@media (max-width: 1400px) {\n  .video-background {\n    transform: translate(-50%, -50%) scale(1.7);\n    max-height: 90vh;\n  }\n}\n/* Schermi sotto i 900px: video ancora più grande */\n@media (max-width: 900px) {\n  .video-background {\n    transform: translate(-50%, -50%) scale(2);\n    max-height: 95vh;\n  }\n}\n/* Schermi sotto i 700px: video massimo */\n@media (max-width: 750px) {\n  .video-background {\n    transform: translate(-50%, -50%) scale(1.9);\n    max-height: 100vh;\n  }\n}\n@media (max-width: 700px) {\n  .video-background {\n    transform: translate(-50%, -50%) scale(1.8);\n    max-height: 100vh;\n  }\n}\n@media (max-width: 650px) {\n  .video-background {\n    transform: translate(-50%, -50%) scale(2);\n    max-height: 100vh;\n  }\n}\n/* Meta' schermo */\n@media (max-width: 720px) {\n  .banner .cd-headline {\n    font-size: 24px !important;\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 44vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n}\n/* \n==================================\nTelefono\n==================================\n*/\n@media (max-width: 520px) {\n  .video-background {\n    max-height: 100%;\n    max-width: 100%;\n    border-radius: 0px;\n    width: 100%;\n    height: 100%;\n    box-shadow: inset 0px 0px 30px 30px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 30vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n  /*\n  ==================================\n  Portfolio-home\n  ==================================\n  */\n  label.btn {\n    font-size: 13px;\n    padding: 20px 10px 10px 0px !important;\n  }\n  p.short-text {\n    display: contents;\n  }\n  p.full-text {\n    display: none;\n  }\n  .stat {\n    font-size: 3vw;\n  }\n}\n@media (min-width: 521px) {\n  p.short-text {\n    display: none;\n  }\n  p.full-text {\n    display: contents;\n  }\n}\n/* ============================================\n   CONTENUTO TESTUALE: sopra il video\n   ============================================ */\n.banner .container {\n  position: relative;\n  z-index: 1;\n  width: 100%;\n}\n\n/* Colonna del testo centrata con larghezza controllata */\n.banner .container .col-lg-10 {\n  margin: 0 auto;\n  float: none;\n}\n\n/* Testo in contrasto con il video */\n.banner h2,\n.banner p {\n  color: white;\n  text-shadow: 0 2px 15px rgba(0, 0, 0, 0.7);\n}\n\n.copy-btn {\n  background: transparent;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n  color: inherit; /* Eredita il colore dal testo circostante */\n  font: inherit; /* Eredita il font */\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n\n.copy-btn:hover {\n  color: #f44336;\n}\n\n.toast {\n  position: fixed;\n  bottom: 30px;\n  left: 50%;\n  transform: translateX(-50%) translateY(100px);\n  background: #ffffff;\n  color: #222;\n  padding: 14px 32px;\n  border-radius: 30px;\n  font-size: 0.95rem;\n  font-weight: 500;\n  letter-spacing: 0.3px;\n  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.35);\n  opacity: 0;\n  transition: opacity 0.4s ease, transform 0.4s ease;\n  z-index: 9999;\n  pointer-events: none;\n  white-space: nowrap;\n}\n\n.toast.show {\n  opacity: 1;\n  transform: translateX(-50%) translateY(0);\n}\n\n/* Cambiano in base alla grandezza del dispositivo */\n/* Su schermi piccoli, abbrevia il testo */\n@media (max-width: 768px) {\n  .stat .full-text {\n    display: none;\n  }\n  .stat .short-text {\n    display: inline;\n  }\n}\n@media (min-width: 769px) {\n  .stat .full-text {\n    display: inline;\n  }\n  .stat .short-text {\n    display: none;\n  }\n}\n@media (max-width: 991px) {\n  .footer-widget {\n    margin-top: 1em !important;\n  }\n}\n@media (max-width: 768px) {\n  .navbar-nav {\n    flex-wrap: nowrap !important;\n  }\n  .navbar-nav .nav-item {\n    white-space: nowrap;\n  }\n}\n/* Navbar: logo a sinistra, link e language switcher a destra */\n.main-nav,\n.main-nav .container,\n.main-nav .navbar-collapse,\n.main-nav .navbar-nav {\n  flex-wrap: nowrap !important;\n  flex-direction: row !important;\n}\n\n.main-nav .container {\n  justify-content: space-between !important;\n  align-items: center !important;\n}\n\n.main-nav .navbar-nav {\n  margin-left: auto !important;\n}\n\n/* Nascondi il bottone hamburger (toggle) */\n.main-nav .navbar-toggler {\n  display: none !important;\n}\n\n/* Forza il menu collassabile a essere sempre visibile */\n.main-nav .navbar-collapse {\n  display: flex !important;\n  visibility: visible !important;\n  overflow: visible !important;\n}\n\n.main-nav .navbar-nav {\n  display: flex !important;\n}\n\n.main-nav .nav-item {\n  white-space: nowrap !important;\n  flex-shrink: 1 !important;\n  align-content: center !important;\n}\n\n.main-nav .navbar-brand img {\n  width: 40px !important;\n  height: auto !important;\n  max-width: none !important;\n}\n\n.main-nav .nav-link {\n  white-space: nowrap !important;\n  padding: 0.2rem 0.3rem !important;\n  font-size: 0.8rem !important;\n}\n\n.main-nav .language-switcher {\n  white-space: nowrap !important;\n  flex-shrink: 0 !important;\n}\n\n.main-nav .lang-slider {\n  display: block !important;\n}",".portfolio-options\r\n{\r\n    margin-bottom: 1em !important;\r\n}\r\n\r\n/* ============================================\r\n   BANNER: contenitore principale\r\n   ============================================ */\r\n.banner {\r\n    position: relative;\r\n    min-height: 82vh;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    overflow: hidden; /* 👈 nasconde l'overflow del banner */\r\n}\r\n\r\n/* ============================================\r\n   VIDEO BACKGROUND: sfondo centrato (dietro al testo)\r\n   ============================================ */\r\n.video-background {\r\n    position: absolute;      /* 👈 sta dietro al testo, non esce dal flusso del banner */\r\n    top: 50%;\r\n    left: 50%;\r\n    transform: translate(-50%, -50%) scale(1.4);  /* 👈 ingrandito del 40%, container e video insieme */\r\n    width: fit-content;      /* 👈 stesso width del video, nessun bordo vuoto */\r\n    height: fit-content;     /* 👈 stesso height del video, nessun bordo vuoto */\r\n    max-width: 95%;          /* 👈 non esce dallo schermo su mobile */\r\n    max-height: 85vh;        /* 👈 dimensione specifica altezza */\r\n    z-index: 0;              /* 👈 dietro al testo (container ha z-index: 1) */\r\n    overflow: hidden;        /* 👈 taglia il video agli angoli arrotondati del container */\r\n    border-radius: 30px;     /* 👈 bordi arrotondati più visibili sul CONTAINER */\r\n    box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\r\n}\r\n\r\n/* ============================================\r\n   VIDEO: stessa grandezza del container, aspect ratio preservato\r\n   ============================================ */\r\n.video-background video {\r\n    max-width: 100%;         /* 👈 non esce mai dal container in larghezza */\r\n    max-height: 100%;        /* 👈 non esce mai dal container in altezza */\r\n    object-fit: contain;     /* 👈 mantiene l'aspect ratio, nessun taglio */\r\n    opacity: 60%;\r\n    display: block;\r\n    /* nessun position: absolute: sta nel flusso del container */\r\n    /* nessun border-radius: sta solo sul container con overflow: hidden */\r\n}\r\n\r\n/* Schermi sotto i 1400px: video più grande */\r\n@media (max-width: 1400px) {\r\n    .video-background {\r\n        transform: translate(-50%, -50%) scale(1.7);\r\n        max-height: 90vh;\r\n    }\r\n}\r\n\r\n/* Schermi sotto i 900px: video ancora più grande */\r\n@media (max-width: 900px) {\r\n    .video-background {\r\n        transform: translate(-50%, -50%) scale(2.0);\r\n        max-height: 95vh;\r\n    }\r\n}\r\n\r\n/* Schermi sotto i 700px: video massimo */\r\n@media (max-width: 750px) {\r\n    .video-background {\r\n        transform: translate(-50%, -50%) scale(1.9);\r\n        max-height: 100vh;\r\n    }\r\n}\r\n\r\n@media (max-width: 700px) {\r\n    .video-background {\r\n        transform: translate(-50%, -50%) scale(1.8);\r\n        max-height: 100vh;\r\n    }\r\n}\r\n\r\n@media (max-width: 650px) {\r\n    .video-background {\r\n        transform: translate(-50%, -50%) scale(2);\r\n        max-height: 100vh;\r\n    }\r\n}\r\n\r\n\r\n/* Meta' schermo */\r\n@media (max-width: 720px) {\r\n    .video-background {\r\n    }\r\n    \r\n    .banner .cd-headline\r\n    {\r\n        font-size: 24px !important;\r\n    }\r\n    \r\n    .section.banner\r\n    {\r\n        padding: 0px;\r\n        min-height: 44vh;\r\n    }\r\n\r\n    body > section.portfolio > div > div.row.mb-5\r\n    {\r\n        margin-bottom: 15px !important;\r\n    }\r\n}\r\n/* \r\n==================================\r\nTelefono\r\n==================================\r\n*/\r\n@media (max-width: 520px)\r\n{\r\n    .video-background {\r\n        max-height: 100%;\r\n        max-width: 100%;\r\n        border-radius: 0px;\r\n\r\n        width: 100%;\r\n        height: 100%;\r\n        box-shadow: inset 0px 0px 30px 30px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\r\n    }\r\n\r\n    .section.banner\r\n    {\r\n        padding: 0px;\r\n        min-height: 30vh;\r\n    }\r\n\r\n    body > section.portfolio > div > div.row.mb-5\r\n    {\r\n        margin-bottom: 15px !important;\r\n    }\r\n    /*\r\n    ==================================\r\n    Portfolio-home\r\n    ==================================\r\n    */\r\n    label.btn {\r\n        font-size: 13px;\r\n        padding: 20px 10px 10px 0px !important;\r\n    }\r\n\r\n    p.short-text{\r\n        display: contents;\r\n    }\r\n\r\n    p.full-text{\r\n        display:none;\r\n    }\r\n\r\n    .stat {\r\n        font-size: 3vw;\r\n    }\r\n}\r\n@media (min-width: 521px)\r\n{\r\n    p.short-text\r\n    {\r\n        display:none;\r\n    }\r\n    \r\n    p.full-text{\r\n        display:contents;\r\n    }\r\n\r\n}\r\n\r\n\r\n\r\n\r\n/* ============================================\r\n   CONTENUTO TESTUALE: sopra il video\r\n   ============================================ */\r\n.banner .container {\r\n    position: relative;\r\n    z-index: 1;\r\n    width: 100%;\r\n}\r\n\r\n/* Colonna del testo centrata con larghezza controllata */\r\n.banner .container .col-lg-10 {\r\n    margin: 0 auto;\r\n    float: none;\r\n}\r\n\r\n/* Testo in contrasto con il video */\r\n.banner h2,\r\n.banner p {\r\n    color: white;\r\n    text-shadow: 0 2px 15px rgba(0, 0, 0, 0.7);\r\n}\r\n\r\n\r\n\r\n\r\n\r\n.copy-btn {\r\n    background: transparent;\r\n    border: none;\r\n    padding: 0;\r\n    cursor: pointer;\r\n    color: inherit;          /* Eredita il colore dal testo circostante */\r\n    font: inherit;           /* Eredita il font */\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n    transition: transform 0.2s ease, opacity 0.2s ease;\r\n}\r\n\r\n.copy-btn:hover {\r\n    color: #f44336;\r\n}\r\n\r\n.toast {\r\n    position: fixed;\r\n    bottom: 30px;\r\n    left: 50%;\r\n    transform: translateX(-50%) translateY(100px);\r\n    background: #ffffff;\r\n    color: #222;\r\n    padding: 14px 32px;\r\n    border-radius: 30px;\r\n    font-size: 0.95rem;\r\n    font-weight: 500;\r\n    letter-spacing: 0.3px;\r\n    box-shadow: 0 15px 50px rgba(0, 0, 0, 0.35);\r\n    opacity: 0;\r\n    transition: opacity 0.4s ease, transform 0.4s ease;\r\n    z-index: 9999;\r\n    pointer-events: none;\r\n    white-space: nowrap;\r\n}\r\n\r\n.toast.show {\r\n    opacity: 1;\r\n    transform: translateX(-50%) translateY(0);\r\n}\r\n\r\n\r\n\r\n\r\n/* Cambiano in base alla grandezza del dispositivo */\r\n/* Su schermi piccoli, abbrevia il testo */\r\n@media (max-width: 768px) {\r\n    .stat .full-text {\r\n        display: none;\r\n    }\r\n    .stat .short-text {\r\n        display: inline;\r\n    }\r\n}\r\n\r\n@media (min-width: 769px) {\r\n    .stat .full-text {\r\n        display: inline;\r\n    }\r\n    .stat .short-text {\r\n        display: none;\r\n    }\r\n}\r\n\r\n@media (max-width: 991px)\r\n{\r\n    .footer-widget\r\n    {\r\n        margin-top: 1em !important;\r\n    }\r\n}\r\n\r\n@media (max-width: 768px) {\r\n    .navbar-nav {\r\n        flex-wrap: nowrap !important;\r\n    }\r\n    \r\n    .navbar-nav .nav-item {\r\n        white-space: nowrap;\r\n    }\r\n}\r\n\r\n/* Navbar: logo a sinistra, link e language switcher a destra */\r\n.main-nav,\r\n.main-nav .container,\r\n.main-nav .navbar-collapse,\r\n.main-nav .navbar-nav {\r\n    flex-wrap: nowrap !important;\r\n    flex-direction: row !important;\r\n}\r\n\r\n.main-nav .container {\r\n    justify-content: space-between !important;\r\n    align-items: center !important;\r\n}\r\n\r\n.main-nav .navbar-nav {\r\n    margin-left: auto !important;\r\n}\r\n\r\n/* Nascondi il bottone hamburger (toggle) */\r\n.main-nav .navbar-toggler {\r\n    display: none !important;\r\n}\r\n\r\n/* Forza il menu collassabile a essere sempre visibile */\r\n.main-nav .navbar-collapse {\r\n    display: flex !important;\r\n    visibility: visible !important;\r\n    overflow: visible !important;\r\n}\r\n\r\n.main-nav .navbar-nav {\r\n    display: flex !important;\r\n}\r\n\r\n.main-nav .nav-item {\r\n    white-space: nowrap !important;\r\n    flex-shrink: 1 !important;\r\n    align-content: center !important;\r\n}\r\n\r\n.main-nav .navbar-brand img {\r\n    width: 40px !important;\r\n    height: auto !important;\r\n    max-width: none !important;\r\n}\r\n\r\n.main-nav .nav-link {\r\n    white-space: nowrap !important;\r\n    padding: 0.2rem 0.3rem !important;\r\n    font-size: 0.8rem !important;\r\n}\r\n\r\n.main-nav .language-switcher {\r\n    white-space: nowrap !important;\r\n    flex-shrink: 0 !important;\r\n}\r\n\r\n.main-nav .lang-slider {\r\n    display: block !important;\r\n}"]}